def comps(grid,color):
    H,W=len(grid),len(grid[0]); seen=set(); res={}
    for i in range(H):
        for j in range(W):
            if grid[i][j]==color and (i,j) not in seen:
                st=[(i,j)]; seen.add((i,j)); c=[]
                while st:
                    y,x=st.pop(); c.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and grid[ny][nx]==color and (ny,nx) not in seen:
                            seen.add((ny,nx)); st.append((ny,nx))
                for p in c: res[p]=c
    return res

